INSERT INTO legislation_scope (legislation_id, product_group_id, note) VALUES
  ('espr', 'aluminium', 'Aluminium is a priority intermediate product in the 2025–2030 working plan; delegated act with DPP expected around 2027.'),
  ('espr', 'textile', 'Textiles (apparel) are a priority group; delegated act expected around 2027. Ban on destroying unsold apparel and footwear from 19 July 2026.'),
  ('cpr', 'aluminium', 'Aluminium construction products (profiles, windows, curtain walling, cladding). Applies from 8 January 2026, product family by product family.'),
  ('ppwr', 'aluminium', 'Aluminium packaging (cans, foil, trays, tubes, aerosols). Applies from 12 August 2026.'),
  ('cbam', 'aluminium', 'Unwrought aluminium and aluminium products (CN 7601, 7603–7616) imported into the EU. Definitive period since 1 January 2026; importers under 50 tonnes net mass a year are exempt.'),
  ('reach', 'aluminium', 'Substances of very high concern in articles; Annex XVII restrictions that apply to metal articles.'),
  ('reach', 'textile', 'Substances of very high concern in articles; textile-specific restrictions in Annex XVII.'),
  ('bpr', 'textile', 'Treated articles, e.g. antibacterial, anti-odour or anti-mould textiles.'),
  ('tlr', 'textile', 'All textile products made available on the EU market.'),
  ('gpsr', 'textile', 'Consumer textile products. Applies since 13 December 2024.'),
  ('wfd', 'aluminium', 'SCIP notification of articles containing substances of very high concern.'),
  ('wfd', 'textile', 'SCIP notification, plus extended producer responsibility for textiles and footwear: schemes operational by April 2028.'),
  ('flr', 'aluminium', 'Ban on products made with forced labour, e.g. in bauxite mining or smelting. Applies from 14 December 2027.'),
  ('flr', 'textile', 'Ban on products made with forced labour, e.g. in cotton farming or garment making. Applies from 14 December 2027.'),
  ('catena-x', 'aluminium', 'For aluminium supplied into vehicles. Not law: you join to exchange data with automotive customers. Its footprint rulebook and tariff standard both address aluminium directly.'),
  ('catena-x', 'textile', 'Only for textile parts supplied into vehicles, such as seat covers. No standard is specific to textiles, and apparel and home textiles are outside its automotive scope.'),
  ('gots', 'textile', 'Every processing stage, from fibre to finished product. Two label grades: Organic with at least 95% certified organic fibres, and Made with Organic Materials with at least 70%.'),
  ('ocs', 'textile', 'Verifies organic content and its chain of custody, without the processing criteria GOTS adds. Moving into the Materials Matter Standard, mandatory from 31 December 2027.'),
  ('ivn-best', 'textile', 'GOTS plus ten further requirements, so a certified company must hold GOTS too. Accepts only 100% organic natural fibre, trims aside.'),
  ('oeko-organic', 'textile', 'Organic cotton verified from farm to product, with laboratory tests on the product itself.'),
  ('roc', 'textile', 'Covers textiles as well as food and personal care. Adds soil health, animal welfare and farmworker fairness to an organic baseline, at Bronze, Silver or Gold.'),
  ('fairtrade-textile', 'textile', 'Factories, workers and brands, only in countries where freedom of association is possible. The revision covers Tier-1 and cut-make-trim factories.'),
  ('fairtrade-cotton', 'textile', 'Marks cotton from Fairtrade certified farmers. It speaks to the cotton, not to the factories that make the garment.'),
  ('fair-trade-usa', 'textile', 'Sets social, environmental and economic requirements for products, producers and businesses, with standards tailored to factories and to agriculture.'),
  ('wfto', 'textile', 'Verifies the whole enterprise rather than a product; a guaranteed member may use the label on its Fair Trade products. WFTO says it is moving to external certification to meet EU requirements.'),
  ('fair-for-life', 'textile', 'Fair trade certification that covers textiles among other goods. The logo may appear when 80% of the raw materials come from Fair Trade.'),
  ('fair-wear', 'textile', 'A brand membership, not a product certification. Only members rated Leader or Good may show the logo on garments.'),
  ('bci', 'textile', 'Cotton farming programme. Sourced as Mass Balance, which tracks volumes, or as Traceable cotton, which is physically segregated, so check which one a claim rests on.'),
  ('cmia', 'textile', 'Cotton from Sub-Saharan Africa. The seal alone can rest on Mass Balance; the "Cotton made in Africa Inside" label means the cotton was kept separate. An Organic variant exists.'),
  ('grs', 'textile', 'Recycled content plus social, environmental and chemical processing requirements. Moving into the Materials Matter Standard, mandatory from 31 December 2027.'),
  ('rcs', 'textile', 'Recycled content and its chain of custody only, without the GRS processing requirements. Moving into the Materials Matter Standard, mandatory from 31 December 2027.'),
  ('rws', 'textile', 'Wool farms and every site up to the final business-to-business seller. Moving into the Materials Matter Standard, mandatory from 31 December 2027.'),
  ('rds', 'textile', 'Down and feathers. Not in the first version of the Materials Matter Standard, so it stays in use for now.'),
  ('rms', 'textile', 'Mohair farms and every site up to the final business-to-business seller. Moving into the Materials Matter Standard, mandatory from 31 December 2027.'),
  ('ras', 'textile', 'Alpaca farms and every site up to the final business-to-business seller. Moving into the Materials Matter Standard, mandatory from 31 December 2027.'),
  ('downpass', 'textile', 'Standard and label for down and feathers used as filling.'),
  ('gcs', 'textile', 'Cashmere from Inner Mongolia, covering goats, herders and the environment.'),
  ('vegan-trademark', 'textile', 'Registered per product, not per brand, and open to clothing.'),
  ('peta-vegan', 'textile', 'Marks textiles free of animal materials, after a review of the company by PETA.'),
  ('oeko-100', 'textile', 'Tests all components for harmful substances, from yarn to finished product. It does not address organic content or working conditions.'),
  ('oeko-mig', 'textile', 'Textiles and leather tested for harmful substances and traceable to socially responsible, environmentally managed production.'),
  ('bluesign', 'textile', 'Independent certification of consumer products, articles and chemicals, working through the textile value chain from chemicals onward.'),
  ('eu-ecolabel', 'textile', 'The EU''s official ecolabel, with criteria on fibres, chemicals and processes, fitness for use and social responsibility.'),
  ('nordic-swan', 'textile', 'The official Nordic ecolabel, licensed separately for products and for manufacturing. Shoes fall under other criteria.'),
  ('blue-angel', 'textile', 'Germany''s government ecolabel, for products of at least 90% textile fibres by weight, and 70% for bags.'),
  ('green-button', 'textile', 'A government-run label that certifies the company and the product together. Product proof rests on recognised labels such as GOTS, Fairtrade and STANDARD 100.'),
  ('c2c', 'textile', 'Multi-attribute standard for materials and products in general, not only textiles.'),
  ('fsc', 'textile', 'For forest-based fibres such as viscose, lyocell and modal. FSC Recycled is not yet extended to textiles.');
