  ('225', 'working-conditions', 'c2c', 'Cradle to Cradle', 'The Social Fairness category.', NULL, NULL, 'https://c2ccertified.org/the-standard'),
  ('226', 'material-composition', 'fsc', 'FSC', 'Man-made cellulosic fibres sourced from responsibly managed forests.', NULL, NULL, 'https://fsc.org/en/fashion'),
  ('227', 'chain-of-custody', 'fsc', 'FSC', 'Manufacturers hold chain-of-custody certification to trade FSC materials.', NULL, NULL, 'https://fsc.org/en/fashion'),
  ('228', 'label', 'fsc', 'FSC', 'FSC trademarks for certified companies; brands and retailers promote finished goods under a licence.', NULL, NULL, 'https://fsc.org/en/fashion');
