INSERT INTO join_step (id, legislation_id, product_group_id, title, detail, source, url, position) VALUES
  ('textile-scope', 'catena-x', 'textile', 'Check you are in scope', 'Catena-X serves the automotive value chain and no standard is specific to textiles. Carry on only if you supply parts for vehicles or a customer there asks you to.', 'Onboarding guide', 'https://catena-x.net/de/participate', '0'),
  ('use-cases', 'catena-x', NULL, 'Choose your use cases', 'Decide which exchanges your customers need, such as carbon footprint or traceability. They set the data and applications you need later.', 'Onboarding guide', 'https://catena-x.net/de/participate', '1'),
  ('aluminium-use-cases', 'catena-x', 'aluminium', 'Look at footprint and tariffs first', 'These two address aluminium directly: the footprint rulebook has annexes for aluminium methods, and CX-0153 covers tariff data for parts containing aluminium.', 'CX-0153', 'https://catenax-ev.github.io/docs/standards/CX-0153-TariffsUseCase', '2'),
  ('role', 'catena-x', NULL, 'Pick your role', 'A company exchanging its own data is a data provider and consumer. Some roles need a certificate of conformity from a conformity assessment body before registering.', 'Operating model', 'https://catenax-ev.github.io/docs/operating-model/who-roles-in-the-catena-x-ecosystem', '3'),
  ('invitation', 'catena-x', NULL, 'Contact an onboarding service provider', 'Registration is by invitation: it goes through a certified onboarding service provider or the core service provider. Cofinity-X is one place to start.', 'CX-0006', 'https://catenax-ev.github.io/docs/standards/CX-0006-RegistrationAndInitialOnboarding', '4'),
  ('registration-data', 'catena-x', NULL, 'Gather your registration data', 'Company name, full address with country, and VAT ID. A clearing house validates them before your Business Partner Number is issued.', 'Onboarding guide', 'https://catena-x.net/de/participate', '5'),
  ('identity', 'catena-x', NULL, 'Pass identity proofing and choose a wallet', 'The core service provider verifies your identity. Bring your own compliant wallet or have one provided.', 'CX-0149', 'https://catenax-ev.github.io/docs/standards/CX-0149-WalletRequirements', '6'),
  ('credentials', 'catena-x', NULL, 'Receive your BPN and credentials', 'You get a Business Partner Number, and membership, BPN and framework agreement credentials in your wallet. The membership credential completes onboarding.', 'CX-0006', 'https://catenax-ev.github.io/docs/standards/CX-0006-RegistrationAndInitialOnboarding', '7'),
  ('framework', 'catena-x', NULL, 'Sign the General Data Exchange Framework', 'Required before you exchange data with partners. Involve your legal team early.', 'Operating model', 'https://catenax-ev.github.io/docs/operating-model/how-data-space-operations', '8'),
  ('connector', 'catena-x', NULL, 'Get a connector', 'Every participant needs an Eclipse Dataspace Connector: inside a business application, as a managed service, or run in-house. Involve IT early.', 'CX-0018', 'https://catenax-ev.github.io/docs/standards/CX-0018-DataspaceConnectivity', '9'),
  ('certified-solution', 'catena-x', NULL, 'Check certification for your solution', 'Certified applications are ready to exchange data with other participants. CX-0018 also lists data providers and consumers among roles certified against it, so ask your provider what applies to you.', 'CX-0018', 'https://catenax-ev.github.io/docs/standards/CX-0018-DataspaceConnectivity', '10'),
  ('twins', 'catena-x', NULL, 'Model your parts as digital twins', 'Register part types, then batches or serial parts. An upload tool is an option if you don''t integrate your systems directly.', 'CX-0007', 'https://catenax-ev.github.io/docs/standards/CX-0007-MinimalDataProviderServicesOffering', '11'),
  ('aluminium-pcf', 'catena-x', 'aluminium', 'Align your footprint method to the rulebook', 'If you use the European Aluminium or International Aluminium Institute method, check your calculation against the extra requirements in the rulebook''s annexes.', 'PCF Rulebook', 'https://catenax-ev.github.io/docs/rulebooks/CX-NFR-PCF', '12'),
  ('textile-pcf', 'catena-x', 'textile', 'Calculate footprints under the general rules', 'The rulebook has no textile-specific rules, so apply its general ones, and ask your customer what they expect.', 'PCF Rulebook', 'https://catenax-ev.github.io/docs/rulebooks/CX-NFR-PCF', '13'),
  ('data', 'catena-x', NULL, 'Provide the data your use cases need', 'Start with what you already hold for legislation: the list alongside shows which data does double duty.', 'CX-0007', 'https://catenax-ev.github.io/docs/standards/CX-0007-MinimalDataProviderServicesOffering', '14');
